/* ══════════════════════════════════════════════════════════════
   DOM HELPERS
══════════════════════════════════════════════════════════════ */

/**
 * Safely query a selector; throws a clear error if missing
 * @param {string} selector
 * @param {Element} [parent]
 * @returns {Element}
 */
function qs(selector, parent = document) {
  const el = parent.querySelector(selector);
  if (!el) {
    console.warn(`Element not found: ${selector}`);
  }
  return el;
}

/**
 * Query all matching elements
 * @param {string} selector
 * @param {Element} [parent]
 * @returns {NodeList}
 */
function qsa(selector, parent = document) {
  return parent.querySelectorAll(selector);
}

/**
 * Create element with optional class and text
 * @param {string} tag
 * @param {string} [className]
 * @param {string} [text]
 * @returns {HTMLElement}
 */
function createElement(tag, className, text) {
  const el = document.createElement(tag);
  if (className) el.className = className;
  if (text !== undefined) el.textContent = text;
  return el;
}

/**
 * Show an element (remove hidden class)
 * @param {Element} el
 */
function showEl(el) {
  if (el) el.classList.remove('hidden');
}

/**
 * Hide an element (add hidden class)
 * @param {Element} el
 */
function hideEl(el) {
  if (el) el.classList.add('hidden');
}

/**
 * Toggle hidden state
 * @param {Element} el
 */
function toggleEl(el) {
  if (el) el.classList.toggle('hidden');
}

/**
 * Attach a theme toggle button
 * @param {HTMLElement} btn
 */
function attachThemeToggle(btn) {
  if (!btn) return;
  btn.addEventListener('click', () => {
    toggleTheme();
  });
}

